<?php
namespace App\Http\Controllers\Procurement;use App\Http\Controllers\Controller;use App\Models\{GoodsReceivedNote,PurchaseOrder,Store};use App\Services\Procurement\ProcurementService;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class GrnController extends Controller{public function index(){ $p=auth()->user()->property_id;return view('procurement.grns.index',['rows'=>GoodsReceivedNote::with(['order.supplier','store','items.inventoryItem'])->where('property_id',$p)->latest()->paginate(30),'orders'=>PurchaseOrder::with('items.inventoryItem')->where('property_id',$p)->whereIn('status',['approved','sent','part_received'])->get(),'stores'=>Store::where('property_id',$p)->where('is_active',1)->get()]);}public function store(Request $r){$d=$r->validate(['purchase_order_id'=>'required|integer','store_id'=>'required|integer','delivery_note_number'=>'nullable|max:100','purchase_order_item_id'=>'required|array|min:1','purchase_order_item_id.*'=>'required|integer','quantity_received'=>'required|array','quantity_received.*'=>'required|numeric|min:0','quantity_rejected'=>'nullable|array','unit_cost'=>'required|array','unit_cost.*'=>'required|numeric|min:0','batch_number'=>'nullable|array','expires_at'=>'nullable|array']);DB::transaction(function()use($d){$p=auth()->user()->property_id;$po=PurchaseOrder::where('property_id',$p)->findOrFail($d['purchase_order_id']);$grn=GoodsReceivedNote::create(['property_id'=>$p,'purchase_order_id'=>$po->id,'store_id'=>$d['store_id'],'number'=>'GRN-'.now()->format('Ymd-His').'-'.random_int(10,99),'received_date'=>today(),'delivery_note_number'=>$d['delivery_note_number']??null,'received_by'=>auth()->id()]);foreach($d['purchase_order_item_id'] as $i=>$poItemId){$poItem=$po->items()->findOrFail($poItemId);$grn->items()->create(['purchase_order_item_id'=>$poItemId,'inventory_item_id'=>$poItem->inventory_item_id,'quantity_received'=>$d['quantity_received'][$i],'quantity_rejected'=>$d['quantity_rejected'][$i]??0,'unit_cost'=>$d['unit_cost'][$i],'batch_number'=>$d['batch_number'][$i]??null,'expires_at'=>$d['expires_at'][$i]??null]);}});return back()->with('success','GRN created. Post it to update stock.');}public function post(GoodsReceivedNote $grn,ProcurementService $svc){abort_unless($grn->property_id===auth()->user()->property_id,403);$svc->postGrn($grn,auth()->id());return back()->with('success','GRN posted and stock updated.');}}